// Runs a helper script as Node.js and Bun programs do: the runtime itself (process.execPath)
// given the script's path, found from this module's URL.
import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";

export default function run() {
  const script = fileURLToPath(new URL("./helper.ts", import.meta.url));
  const r = spawnSync(process.execPath, [script, "a", "b c"], { encoding: "utf8" });
  console.log("helper said:", r.stdout.trim());
  console.log("status:", r.status);
  console.log("main here:", import.meta.main);
}
